import type { ImageSourcePropType } from 'react-native';

import manifest from '@/assets/exercise-media/manifest.json';
import { EXERCISE_MEDIA_FILES } from '@/assets/exercise-media';
import type { Exercise } from '@/types/workout';

/**
 * Bundled exercise illustrations (ADR-004 / ADR-007). `manifest.json` and
 * `index.ts` are generated by scripts/media/import-repdb.mjs from the exact
 * RepDB mapping; nothing here is hand-edited. Custom exercises use the
 * user's own photo (`Exercise.imageUri`); everything else gets the fallback.
 */

export type MediaKind = 'still_pair' | 'still_single' | 'none';

interface ManifestFile {
  file: string;
  sha256: string;
  width: number;
  height: number;
  bytes: number;
}

export interface ManifestEntry {
  kind: MediaKind;
  source: 'repdb' | null;
  sourceId?: string;
  sourceName?: string;
  license?: string;
  attribution?: string;
  files?: Partial<Record<'start' | 'end' | 'main', ManifestFile>>;
  nearest?: string;
  reason?: string;
}

export interface ExerciseMedia {
  kind: 'still_pair' | 'still_single' | 'user_photo' | 'none';
  /** Start position (or the single frame). */
  start: ImageSourcePropType | null;
  /** End position for pairs. */
  end: ImageSourcePropType | null;
  attribution: string | null;
}

export const MEDIA_MANIFEST = manifest as { source: { attribution: string; license: string; repository: string }; entries: Record<string, ManifestEntry> };

const FILES = EXERCISE_MEDIA_FILES as Record<string, Partial<Record<'start' | 'end' | 'main', ImageSourcePropType>>>;

const NO_MEDIA: ExerciseMedia = { kind: 'none', start: null, end: null, attribution: null };

/** Resolves what to draw for an exercise. Pure; safe to call on every render. */
export function getExerciseMedia(exercise: Pick<Exercise, 'id' | 'imageUri'> | null | undefined): ExerciseMedia {
  if (!exercise) return NO_MEDIA;
  if (exercise.imageUri) return { kind: 'user_photo', start: { uri: exercise.imageUri }, end: null, attribution: null };
  const entry = MEDIA_MANIFEST.entries[exercise.id];
  const files = FILES[exercise.id];
  if (!entry || entry.kind === 'none' || !files) return NO_MEDIA;
  if (entry.kind === 'still_pair' && files.start && files.end) {
    return { kind: 'still_pair', start: files.start, end: files.end, attribution: entry.attribution ?? null };
  }
  const single = files.main ?? files.start ?? null;
  return single ? { kind: 'still_single', start: single, end: null, attribution: entry.attribution ?? null } : NO_MEDIA;
}

export const hasBundledMedia = (exerciseId: string): boolean => {
  const entry = MEDIA_MANIFEST.entries[exerciseId];
  return entry !== undefined && entry.kind !== 'none';
};
